import numpy as np, base64, json, sys

SR = 44100

def b64_int16(x):
    x = np.clip(np.asarray(x, dtype=float), -1, 1)
    d = (x * 32767).astype('<i2').tobytes()
    return base64.b64encode(d).decode()

def write(path, x):
    with open(path, 'w') as f:
        json.dump(b64_int16(x), f)
