{"command": "cd /workspace && cat > work/xmparse.py <<'EOF'
import struct, numpy as np, sys

def load(path):
    d = open(path,'rb').read()
    assert d[:17]==b'Extended Module:', 'not xm'
    name = d[17:37].rstrip(b'\0').decode('latin1')
    off = 60
    hdrlen = struct.unpack('<I', d[58:62])[0]
    songlen, restart, nch, npat, ninst, flags, tempo, bpm = struct.unpack('<HHHHHHHH', d[62:78])
    order = list(d[78:78+songlen])
    pos = 78 + ((songlen+255)//256)*256
    patterns = []
    for _ in range(npat):
        plen, ptype, nrows, packed = struct.unpack('<IBHH', d[pos:pos+10])
        pos += 10
        if packed == 0:
            data = bytearray()
            for r in range(nrows):
                for c in range(nch):
                    data += bytearray(d[pos:pos+5]); pos += 5
        else:
            data = bytearray()
            end = pos + packed
            while pos < end:
                b = d[pos]; pos += 1
                if b & 0x80:
                    cnt = b & 0x1f
                    for k in range(5):
                        if b & (1 << (5+k)):
                            data.append(d[pos]); pos += 1
                        else:
                            data.append(0)
                    for extra in range(cnt):
                        for k in range(5):
                            if b & (1 << (5+k)):
                                data.append(d[pos]); pos += 1
                            else:
                                data.append(0)
                else:
                    for k in range(5):
                        if b & (1 << (4+k)):
                            data.append(d[pos]); pos += 1
                        else:
                            data.append(0)
        grid = [[tuple(data[(r*nch+c)*5:(r*nch+c)*5+5]) for c in range(nch)] for r in range(nrows)]
        patterns.append(grid)
    instruments = []
    for _ in range(ninst):
        size, = struct.unpack('<I', d[pos:pos+4])
        start = pos
        name = d[pos+4:pos+26].rstrip(b'\0').decode('latin1')
        itype = d[pos+26]
        nsamp, = struct.unpack('<H', d[pos+27:pos+29])
        samples = []
        if nsamp > 0:
            shsize, = struct.unpack('<I', d[pos+29:pos+33])
            for i in range(16):
                _, = struct.unpack('<I', d[pos+33+40*i:pos+37+40*i])
            # sample headers start at start+33+16*40? standard: after sample header size field there are 96 separated note numbers then 16 headers
            pass
        # simpler: read 16 sample headers at start+29+4+96? Let's use standard size approach
        instruments.append(dict(name=name, nsamp=nsamp))
        pos = start + size
    return dict(name=name, nch=nch, npat=npat, tempo=tempo, bpm=bpm, order=order, patterns=patterns, rest=d[pos:])

if __name__=='__main__':
    m = load(sys.argv[1])
    print(m['name'], m['nch'], m['npat'], 'bpm',m['bpm'],'spd',m['tempo'], 'order', m['order'])
    for i,p in enumerate(m['patterns']):
        used = sum(1 for r in p for c in r if any(c))
        print(i, len(p), 'filled cells', used)
    print('trailing bytes', len(m['rest']))
EOF
python3 work/xmparse.py work/probe.xm"}

