import sys, json
sys.path.insert(0,'/workspace/work')
import numpy as np, music, mkinstr
from music import CH, INSTS, DRUMS, ROOTS, PADS, ARPS, ARP_T, BASS_T, GROOVE, SONG, nstr, NCH

BPM, SPEED = 150, 6
NPAT = (music.NBARS + 3)//4
cells = {}

def put(pat, row, ch, instname, midi=None, vol=None, note=None):
    idx, shift = INSTS[instname]
    args = {"pattern": pat, "row": row, "channel": CH[ch] if isinstance(ch, str) else ch}
    if midi is not None:
        note = nstr(midi + 12*shift)
    if note is not None: args["note"] = note
    args["instrument"] = idx
    if vol is not None:
        args["volume"] = max(1, min(64, int(round(vol))))
    key = (pat, row, args["channel"])
    if key in cells:
        # later writes merge (keep note/inst unless new given)
        cells[key].update({k:v for k,v in args.items() if k not in ('pattern','row','channel')})
    else:
        cells[key] = args

LEVELS = dict(BASS=50, ARP=30, LEAD=46, LEADDET=40, PAD=30)

def write_line(pat, base, chname, instname, notes, level, octv=0, delay=0, volscale=1.0,
               next_has_note0=False):
    if not notes: return
    starts = {r for (r,d,m) in notes}
    for i,(r,d,m) in enumerate(notes):
        row = base + r + delay
        if row >= (pat+1)*64:  # spills into next pattern
            row -= 64
        lvl = level*volscale
        if r == 0: lvl = min(64, lvl*1.08)
        if delay and octv: lvl *= 0.72
        put(pat, row, chname, instname, m+octv, vol=lvl)
        end = r + d + delay
        # articulate when there is a gap
        nxt = None
        for j in range(i+1, len(notes)):
            if notes[j][0] + delay >= end: nxt = notes[j][0]+delay; break
        if nxt is None:
            if end < 16: endrow = base+end
            else: endrow = base+16
            if not (end >= 16 and next_has_note0):
                if endrow < (pat+1)*64:
                    # key off only if nothing else starts there
                    conflict = any((rr+delay) == (endrow-base) for (rr,dd,mm) in notes)
                    if not conflict:
                        put(pat, endrow - (64 if endrow >= (pat+1)*64 else 0), chname, instname,
                            note='===', vol=None)

def build():
    for b, spec in enumerate(SONG):
        pat = b//4; base = (b%4)*16
        vs = spec.get('volscale', 1.0)
        ch = spec['chord']
        # --- drums
        g = GROOVE[spec['groove']]
        for dname, rows in g.items():
            for r in rows:
                lvl = DRUMS[dname]*vs
                if dname in ('CHAT','OHAT'):
                    lvl = lvl*(1.12 if r % 4 == 0 else 0.82)
                put(pat, base+r, CH[dname], dname, note='C-5', vol=lvl)
        if spec.get('crash'):
            put(pat, base, CH['CRASH'], 'CRASH', note='C-5', vol=DRUMS['CRASH']*vs)
        if spec.get('sweep'):
            put(pat, base, CH['SWEEP'], 'SWEEP', note='C-5', vol=DRUMS['SWEEP']*vs)
        # --- bass
        for (r, off) in BASS_T[spec['bass']]:
            lvl = LEVELS['BASS']*vs*(1.1 if r == 0 else 1.0)
            put(pat, base+r, CH['BASS'], 'BASS', ROOTS[ch]+off, vol=lvl)
        # --- arp
        tpl = ARP_T[spec['arp']]
        notes_ar = ARPS[ch]
        for r in range(16):
            if r % spec.get('arp_every', 1): continue
            i = tpl[r % len(tpl)]
            lvl = LEVELS['ARP']*vs*(1.15 if r % 4 == 0 else 0.9)
            put(pat, base+r, CH['ARP'], 'ARP', notes_ar[i]+spec.get('arp_oct', 0), vol=lvl)
        # melody + doubling/echo
        mel = spec.get('melody')
        nxt = None
        if b+1 < music.NBARS:
            nm = SONG[b+1].get('melody')
            nxt = bool(nm) and nm[0][0] == 0
        if mel:
            write_line(pat, base, 'LEAD', 'LEAD', mel, LEVELS['LEAD'], 0, 0, vs, nxt)
            if spec.get('echo'):
                write_line(pat, base, 'LEADDET', 'LEADDET', mel, LEVELS['LEADDET'], 12,
                           spec['echo'], vs, False)
            elif spec.get('dbl'):
                write_line(pat, base, 'LEADDET', 'LEADDET', mel, LEVELS['LEADDET'], 0, 0, vs, False)
