                if last_end >= 16:
                    put(pat, base, CH['LEAD'], 'LEAD', note='===', vol=None)
        # --- pads
        if spec.get('pad', True):
            padnotes = PADS[ch]
            for i, m in enumerate(padnotes):
                put(pat, base, CH['PAD1']+i, 'PAD', m, vol=LEVELS['PAD']*vs)
    # ensure clean loop point: cut sustaining voices on the very last row
    last = (NPAT-1, 63)
    for cname in ('BASS','ARP','LEAD','LEADDET','PAD1','PAD2','PAD3'):
        key = (NPAT-1, 63, CH[cname])
        if key not in cells or 'note' not in cells[key]:
            put(NPAT-1, 63, CH[cname], cname if cname.startswith('PAD') is False else 'PAD', note='===', vol=None)

