import struct
d=open('work/tune.xm','rb').read()
songlen=12; nch=14; npat=12
# try start offsets
for start in range(270, 360):
    pos=start; ok=True; pats=[]
    try:
        for _ in range(npat):
            plen,ptype,nrows,packed=struct.unpack('<IBHH',d[pos:pos+10]); pos+=10
            if not (0<plen<20 and ptype==0 and 0<nrows<=256 and packed>0): ok=False; break
            end=pos+packed; p=pos
            cnt=0
            while p<end:
                b=d[p]; p+=1
                if b&0x80:
                    cnt+=1+(b&0x1f)
                    for k in range(5):
                        if b&(1<<(5+k)): p+=1
                    for k in range(5):
                        if b&(1<<(5+k)): p+=1+b'\x00'.find(b'\x00')  # noop
                    for _ in range(b&0x1f): 
                        for k in range(5):
                            if b&(1<<(5+k)): p+=1
                else:
                    cnt+=1
                    for k in range(4):
                        if b&(1<<(4+k)): p+=1
            if p!=end: ok=False; break
            pats.append((plen,nrows,packed,cnt))
            pos=end
        if ok and pats[0][2]>0:
            print('start',start,'ok', [ (x[1],x[2],x[3]) for x in pats][:3], 'last pos',pos)
    except Exception as e:
        pass
EOF"}

