{"command": "cd /workspace && python3 - <<'EOF'
import numpy as np, wave
NM=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']
def NAME(f):
    m=int(round(69+12*np.log2(f/440)))
    return NM[m%12]+str(m//12-1)
for chan,f in [(8,'/workspace/work/solo_lead.wav')]:
    w=wave.open(f); fr=w.getframerate()
    a=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float).reshape(-1,2)[:,0]
    row=int(fr*6/(150*0.4))
    def pf(rowidx, lo=200, hi=2600):
        seg=a[rowidx*row+300:(rowidx+1)*row-100]
        seg=seg-seg.mean()
        if np.abs(seg).max()<300: return None
        F=np.abs(np.fft.rfft(seg*np.hanning(len(seg)))); fq=np.fft.rfftfreq(len(seg),1/fr)
        m=(fq>lo)&(fq<hi); k=np.argmax(F[m]); f0=fq[m][k]
        num=0; tot=0
        for h in range(1,7):
            mm=(fq>h*f0-25)&(fq<h*f0+25)
            if mm.sum(): num+=F[mm].sum()*(fq[mm][np.argmax(F[mm])]/h); tot+=F[mm].sum()
        return num/tot if tot>0 else f0
    for rng in [range(20,28), range(36,40), range(40,48)]:
        print('---')
        for b in rng:
            print(f'bar{b:2d}:', ' '.join('..' if pf(b*16+r) is None else NAME(pf(b*16+r)) for r in range(16)))
EOF"}

